  const response = await api.post('/send-alert', {
    risk_level: riskLevel,
    message: message,
    alert_type: 'manual',
  });
  return response.data;
};

/**
 * Get alert history
 * @param {number} limit - Max alerts to return
 * @returns {Promise<Object>} Alert history
 */
export const getAlertHistory = async (limit = 20) => {
  const response = await api.get(`/alerts/history?limit=${limit}`);
  return response.data;
};

/**
 * Get alert statistics
 * @returns {Promise<Object>} Alert stats
 */
export const getAlertStats = async () => {
  const response = await api.get('/alerts/stats');
  return response.data;
};

/**
 * Get available YOLO models
 * @returns {Promise<Object>} Available models list
 */
export const getModels = async () => {
  const response = await api.get('/models');
  return response.data;
};

/**
 * Health check
 * @returns {Promise<Object>} API status
 */
export const healthCheck = async () => {
  const response = await api.get('/health');
  return response.data;
};

export default api;
